INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Polypol immer ein vollkommenes Marktmodell?', 2, '[{"text": "Nein", "correct": true, "because": "Es gibt homogene und heterogene Polypole"}, {"text": "Ja", "correct": false, "because": "Nur homogenes Polypol ist vollkommen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal eines Polypols?', 3, '[{"text": "Viele Marktteilnehmer", "correct": true, "because": "Anbieter und Nachfrager konkurrieren"}, {"text": "Ein dominanter Anbieter", "correct": false, "because": "Das wäre ein Monopol"}, {"text": "Hohe Preisflexibilität", "correct": false, "because": "Preise sind marktdiktiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren ein homogenes Polypol?', 5, '[{"text": "Markttransparenz", "correct": true, "because": "Alle Preise bekannt"}, {"text": "Homogene Güter", "correct": true, "because": "Keine Präferenzen"}, {"text": "Reaktionsverbundenheit", "correct": false, "because": "Typisch für Oligopole"}, {"text": "Preisbeeinflussung", "correct": false, "because": "Anbieter sind Preisnehmer"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Polypol hat viele Anbieter. b) Es garantiert hohe Preise.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Marktbedingungen ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse eines Polypols?', 4, '[{"text": "Wettbewerbsdruck", "correct": false, "because": "Treibt Preise"}, {"text": "Marktanteile", "correct": false, "because": "Zeigen Einfluss"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Markt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Polypol Marktmacht einzelner Anbieter ermöglicht?', 2, '[{"text": "Nein", "correct": true, "because": "Geringer Marktanteil"}, {"text": "Ja", "correct": false, "because": "Kein Anbieter dominiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten zeigen Anbieter in einem Polypol?', 3, '[{"text": "Mengenanpassung", "correct": true, "because": "Preise sind vorgegeben"}, {"text": "Preisfestsetzung", "correct": false, "because": "Nur im Monopol"}, {"text": "Koordinierte Absprachen", "correct": false, "because": "Typisch für Oligopole"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Märkte ähneln einem Polypol?', 5, '[{"text": "Wochenmarkt", "correct": true, "because": "Viele Anbieter, Nachfrager"}, {"text": "Börsenmarkt", "correct": true, "because": "Hohe Transparenz"}, {"text": "Strommarkt", "correct": false, "because": "Oft Oligopol"}, {"text": "Postdienst", "correct": false, "because": "Eher Monopol"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Polypol fördert Wettbewerb. b) Es führt immer zu Gewinnmaximierung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Polypol zu analysieren?', 4, '[{"text": "Angebot und Nachfrage", "correct": false, "because": "Bestimmen Preis"}, {"text": "Markttransparenz", "correct": false, "because": "Definiert Polypol"}, {"text": "Mitarbeiteranzahl", "correct": true, "because": "Kein Marktmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Polypol dasselbe wie ein Monopol?', 2, '[{"text": "Nein", "correct": true, "because": "Monopol hat einen Anbieter"}, {"text": "Ja", "correct": false, "because": "Polypol hat viele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften fördern ein Polypol?', 4, '[{"text": "Niedrige Markteintrittsbarrieren", "correct": true, "because": "Erleichtern Wettbewerb"}, {"text": "Markttransparenz", "correct": true, "because": "Alle Preise bekannt"}, {"text": "Preisabsprachen", "correct": false, "because": "Typisch für Oligopole"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Polypol realitätsfern ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Vollkommenes Polypol selten"}, {"text": "Nein", "correct": false, "because": "Idealisierte Annahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Untersuchung eines Polypols?', 3, '[{"text": "Marktmechanismus", "correct": true, "because": "Bestimmt Preisbildung"}, {"text": "Einzelne Marktmacht", "correct": false, "because": "Fehlt im Polypol"}, {"text": "Manuelle Preisgestaltung", "correct": false, "because": "Markt regelt Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Polypol hat keine Interdependenz. b) Es benötigt immer Preisabsprachen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist für Oligopole"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Polypol?', 5, '[{"text": "Niedrige Preise", "correct": true, "because": "Wettbewerb senkt Kosten"}, {"text": "Hohe Auswahl", "correct": true, "because": "Viele Anbieter"}, {"text": "Marktbeherrschung", "correct": false, "because": "Fehlt im Polypol"}, {"text": "Koordinierte Preise", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Polypol unwichtig?', 3, '[{"text": "Angebot-Nachfrage-Balance", "correct": false, "because": "Bestimmt Markt"}, {"text": "Wettbewerbsstruktur", "correct": false, "because": "Definiert Polypol"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Polypol Innovation hemmt?', 2, '[{"text": "Nein", "correct": true, "because": "Wettbewerb fördert Innovation"}, {"text": "Ja", "correct": false, "because": "Innovation durch Konkurrenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Polypol für Preisbildung entscheidend?', 3, '[{"text": "Ja", "correct": true, "because": "Marktmechanismus setzt Preis"}, {"text": "Nein", "correct": false, "because": "Preis durch Angebot-Nachfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Polypol?', 4, '[{"text": "Lebensmittelmarkt", "correct": true, "because": "Viele Anbieter, Nachfrager"}, {"text": "Strommarkt", "correct": false, "because": "Oft Oligopol"}, {"text": "Einzelnes Unternehmen", "correct": false, "because": "Kein Polypol"}]');
